+    reg        flag;
+    reg [15:0] pending_data;
+    reg        pending_valid;
+
+    always @(posedge clk or negedge rst_n) begin
+        if (~rst_n) begin
+            data_r       <= 8'd0;
+            flag         <= 1'b0;
+            pending_data <= 16'd0;
+            pending_valid<= 1'b0;
+            data_out     <= 16'd0;
+            valid_out    <= 1'b0;
+        end else begin
+            valid_out <= pending_valid;
+            if (pending_valid)
+                data_out <= pending_data;
+
+            pending_valid <= 1'b0;
+
+            if (valid_in) begin
+                if ("'!flag) begin
+                    data_r <= data_in;
+                    flag   <= 1'"'b1;
+                end else begin
+                    pending_data  <= {data_r, data_in};
+                    pending_valid <= 1'b1;
+                    flag          <= 1'b0;
+                end
+            end
+        end
+    end
+endmodule
*** End Patch
PATCH
iverilog -g2012 -o simv TopModule.sv"

