/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  reg valid_in = 0;
  reg [7:0] data_in = 0;
  wire valid_out;
  wire [15:0] data_out;

  TopModule dut (
    .clk(clk), .rst_n(rst_n), .valid_in(valid_in), .data_in(data_in),
    .valid_out(valid_out), .data_out(data_out)
  );

  always #5 clk = ~clk;

  task send(input [7:0] b);
    begin
      @(negedge clk);
      valid_in = 1;
      data_in = b;
      @(negedge clk);
      valid_in = 0;
      data_in = 0;
    end
  endtask

  initial begin
    repeat (2) @(negedge clk);
    rst_n = 1;

    send(8'h12);
    send(8'h34);
    repeat (2) @(negedge clk);
    if ("'!(valid_out === 1'"'b1 && data_out === 16'h1234)) begin
      "'$display("FAIL1 valid_out=%0b data_out=%04h", valid_out, data_out);
      $finish_and_return(1);
    end
    @(negedge clk);
    if (valid_out !== 1'"'b0) begin
      "'$display("FAIL2 valid_out=%0b", valid_out);
      $finish_and_return(1);
    end

    send(8'"'hab);
    @(negedge clk);
    if (valid_out "'!== 1'"'b0) begin
      "'$display("FAIL3 valid_out=%0b", valid_out);
      $finish_and_return(1);
    end
    send(8'"'hcd);
    repeat (2) @(negedge clk);
    if ("'!(valid_out === 1'"'b1 && data_out === 16'habcd)) begin
      "'$display("FAIL4 valid_out=%0b data_out=%04h", valid_out, data_out);
      $finish_and_return(1);
    end

    $display("PASS");
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

